ALTER TABLE "libro_de_compras"."retenciones" ADD COLUMN "resolucion" text;--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD COLUMN "nota_de_resolucion" text;--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD COLUMN "resuelta_en" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD COLUMN "resuelta_por" uuid;--> statement-breakpoint
CREATE INDEX "retenciones_por_resolver_idx" ON "libro_de_compras"."retenciones" USING btree ("empresa_id") WHERE "libro_de_compras"."retenciones"."resolucion" = 'pendiente';--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD CONSTRAINT "retenciones_resolucion_valida" CHECK ("libro_de_compras"."retenciones"."resolucion" is null or "libro_de_compras"."retenciones"."resolucion" in ('pendiente', 'constancia_anulada', 'rectificada', 'no_requiere'));--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD CONSTRAINT "retenciones_resolucion_solo_practicada" CHECK ("libro_de_compras"."retenciones"."resolucion" is null or "libro_de_compras"."retenciones"."monto" > 0);--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD CONSTRAINT "retenciones_resolucion_completa" CHECK (("libro_de_compras"."retenciones"."resolucion" in ('constancia_anulada', 'rectificada', 'no_requiere') and "libro_de_compras"."retenciones"."resuelta_en" is not null and "libro_de_compras"."retenciones"."resuelta_por" is not null and "libro_de_compras"."retenciones"."nota_de_resolucion" is not null) or (("libro_de_compras"."retenciones"."resolucion" is null or "libro_de_compras"."retenciones"."resolucion" = 'pendiente') and "libro_de_compras"."retenciones"."resuelta_en" is null and "libro_de_compras"."retenciones"."resuelta_por" is null and "libro_de_compras"."retenciones"."nota_de_resolucion" is null));--> statement-breakpoint
ALTER TABLE "libro_de_compras"."retenciones" ADD CONSTRAINT "retenciones_nota_de_resolucion_rango" CHECK ("libro_de_compras"."retenciones"."nota_de_resolucion" is null or char_length("libro_de_compras"."retenciones"."nota_de_resolucion") between 1 and 300);--> statement-breakpoint
UPDATE "libro_de_compras"."retenciones" r SET "resolucion" = 'pendiente' FROM "libro_de_compras"."documentos" d WHERE d."id" = r."documento_id" AND d."empresa_id" = r."empresa_id" AND d."estado" = 'anulado' AND r."monto" > 0;
